"""Signed API tokens and user lookups."""

import hashlib
import hmac
import json
import sqlite3

MAX_FAILED_VERIFICATIONS = 5
LOCKOUT_SECONDS = 900


def _signature(payload: str, secret: str) -> str:
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def sign_token(payload: str, secret: str) -> str:
    """Return ``payload`` with its hex HMAC-SHA256 signature appended."""
    return f"{payload}.{_signature(payload, secret)}"


def verify_token(token: str, secret: str, now_ts: int, ttl_seconds: int = 3600) -> dict:
    """Return the claims of ``token`` once its signature and age have been checked."""
    payload, _, signature = token.rpartition(".")
    if not hmac.compare_digest(signature.encode(), _signature(payload, secret).encode()):
        raise ValueError("invalid token")
    claims = json.loads(payload)
    if now_ts - claims["iat"] >= ttl_seconds:
        raise ValueError("invalid token")
    return claims


def find_user_by_email(conn: sqlite3.Connection, email: str) -> dict | None:
    """Return the user registered under ``email``, or None if there is none."""
    cursor = conn.execute("SELECT id, email, vip_tier FROM users WHERE email = ?", (email,))
    row = cursor.fetchone()
    if row is None:
        return None
    columns = [column[0] for column in cursor.description]
    return dict(zip(columns, row, strict=True))


class TokenLockout:
    """Lock a user out after too many failed token verifications.

    The caller identifies the user (e.g. from the request context) and calls
    :meth:`verify`; each failed verification is recorded per user and the user
    is locked out once ``max_failed_attempts`` failures accumulate within
    ``lockout_seconds``. A successful verification clears the failures.
    """

    def __init__(self, max_failed_attempts: int = MAX_FAILED_VERIFICATIONS, lockout_seconds: int = LOCKOUT_SECONDS):
        self.max_failed_attempts = max_failed_attempts
        self.lockout_seconds = lockout_seconds
        self._failed_attempts: dict[str, list[int]] = {}

    def is_locked_out(self, user_id: str, now_ts: int) -> bool:
        """Return True when ``user_id`` has accumulated too many recent failures."""
        attempts = [ts for ts in self._failed_attempts.get(user_id, []) if now_ts - ts < self.lockout_seconds]
        self._failed_attempts[user_id] = attempts
        return len(attempts) >= self.max_failed_attempts

    def verify(self, token: str, secret: str, user_id: str, now_ts: int, ttl_seconds: int = 3600) -> dict:
        """Verify ``token`` for ``user_id``, counting failures and locking the user out."""
        if self.is_locked_out(user_id, now_ts):
            raise PermissionError("account locked")
        try:
            claims = verify_token(token, secret, now_ts, ttl_seconds)
        except ValueError:
            self._record_failure(user_id, now_ts)
            raise
        self._failed_attempts.pop(user_id, None)
        return claims

    def _record_failure(self, user_id: str, now_ts: int) -> None:
        attempts = [ts for ts in self._failed_attempts.get(user_id, []) if now_ts - ts < self.lockout_seconds]
        attempts.append(now_ts)
        self._failed_attempts[user_id] = attempts

